import React, { useEffect, useContext, useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { UserContext } from '../../contexts/UserContext';
import './Header.css';

function Header() {
  const { user, setUser } = useContext(UserContext);
  const [requestCount, setRequestCount] = useState(0);
  const navigate = useNavigate();
  const location = useLocation();

  const checkSession = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_BASE_URL}/user/me`, {
        method: 'GET',
        credentials: 'include',
      });

      if (response.ok) {
        const userData = await response.json();
        console.log('사용자 데이터: ', userData);
        setUser(userData);

        if (userData.userRole === 'VET') {
          fetchRequestCount(userData.userId);
        }
      } else {
        setUser(null);
      }
    } catch (error) {
      console.error('세션 확인 오류:', error);
      setUser(null);
    }
  };

  const fetchRequestCount = async (vetId) => {
    try {
      console.log('요청 보낼 vetId: ', vetId);
      const response = await fetch(
          `${process.env.REACT_APP_API_BASE_URL}/consultations/${vetId}/pendingRequestCount`
      );
      console.log('API 응답 상태 코드: ', response.status);
      if (response.ok) {
        const count = await response.json();
        console.log('미확인 상담 요청 수 데이터 : ', count);
        setRequestCount(count);
        console.log('requestCount 상태: ', count); // 추가된 로그
      } else {
        throw new Error('네트워크 응답 X');
      }
    } catch (error) {
      console.error('응답 에러', error);
    }
  };

  useEffect(() => {
    checkSession();
  }, []);

  useEffect(() => {
    console.log('requestCount가 업데이트되었습니다: ', requestCount);
  }, [requestCount]);

  const handleLogout = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_BASE_URL}/logout`, {
        method: 'POST',
        credentials: 'include',
        redirect: 'manual',
      });

      if (response.ok) {
        sessionStorage.clear();
        setUser(null);
        navigate('/');
      } else {
        console.error('로그아웃 실패:', response);
        alert('로그아웃에 실패했습니다.');
      }
    } catch (error) {
      console.error('로그아웃 중 오류 발생:', error);
      alert('서버 오류가 발생했습니다.');
    }
  };

  const handleNavigateToPage = (e, path) => {
    e.preventDefault(); // Prevent default link behavior

    if (location.pathname.startsWith(path) && path === '/mypage') {
      // If already on a sub-route of 'My Page', force navigation to '/mypage'
      navigate(`/mypage?refresh=${new Date().getTime()}`, { replace: true });
    } else if (path === location.pathname) {
      // If already on the same route (other than 'My Page'), force re-render
      navigate(`${path}?refresh=${new Date().getTime()}`, { replace: true });
    } else {
      // Navigate to the specified path
      navigate(path, { replace: true });
    }
  };

  return (
      <header className="header">
        <div className="logo">
          <Link to="/">아토피아</Link>
        </div>
        <nav>
          <ul className="nav-list">
            <li>
              <Link to="/paypage" onClick={(e) => handleNavigateToPage(e, '/paypage')}>
                뼈다귀 구매
              </Link>
            </li>
            <li>
              <Link to="/board/list" onClick={(e) => handleNavigateToPage(e, '/board/list')}>
                라운지
              </Link>
            </li>
            <li>
              <Link to="/hospital" onClick={(e) => handleNavigateToPage(e, '/hospital')}>
                근처 병원
              </Link>
            </li>
            {user && user.userRole === 'CUSTOMER' && (
                <li>
                  <Link to="/clinic/select-pet" onClick={(e) => handleNavigateToPage(e, '/clinic/select-pet')}>
                    클리닉
                  </Link>
                </li>
            )}
            <li>
              <Link to="/store" onClick={(e) => handleNavigateToPage(e, '/store')}>
                스토어
              </Link>
            </li>
            {!user || user.userRole !== 'admin' ? (
                <li>
                  {user ? (
                      <Link to="/mypage" onClick={(e) => handleNavigateToPage(e, '/mypage')}>
                        마이페이지
                      </Link>
                  ) : (
                      <Link to="/login" onClick={() => alert('로그인이 필요합니다.')}>
                        마이페이지
                      </Link>
                  )}
                </li>
            ) : null}
            {user && user.userRole === 'admin' && (
                <li>
                  <Link to="/admin" onClick={(e) => handleNavigateToPage(e, '/admin')}>
                    관리자
                  </Link>
                </li>
            )}
            {user && user.userRole === "VET" && (
                <li>
                  <Link
                      to="/clinic/request"
                      onClick={(e) => handleNavigateToPage(e, "/clinic/request")}
                  >
                    상담 내역 <span className="badge">{pendingCount}</span>
                  </Link>
                </li>
            )}
            {user && (user.userRole === "CUSTOMER" || user.userRole === "VET") && (
                <li>
                  <Link
                      to="/chat"
                      onClick={(e) => handleNavigateToPage(e, "/chat")}
                  >
                    대화창
                  </Link>
                </li>
            )}
            <li>
              {user ? (
                  <Link to="#" onClick={handleLogout}>
                    로그아웃
                  </Link>
              ) : (
                  <Link to="/login">로그인</Link>
              )}
            </li>
          </ul>
        </nav>
      </header>
  );
}

export default Header;
